// Investment Flow API tests for issue #751
// Extended for issue #771 — uninvested cash node
// Extended for issue #776 — uninvested cash categories
// Extended for issue #781 — node highlights (color map)
// Endpoints:
//   GET    /api/investment-flow/v1                              — list nodes (flat adjacency list)
//   POST   /api/investment-flow/v1                              — create node
//   PUT    /api/investment-flow/v1                              — update node (id in body)
//   DELETE /api/investment-flow/v1?id=:uuid                     — delete node + subtree
//   PUT    /api/investment-flow/v1/move                         — move node to new parent
//   GET    /api/investment-flow/v1/uninvested-cash              — get uninvested cash amount
//   PATCH  /api/investment-flow/v1/uninvested-cash              — set uninvested cash amount
//   GET    /api/investment-flow/v1/uninvested-cash/categories   — list cash categories
//   POST   /api/investment-flow/v1/uninvested-cash/categories   — create cash category
//   PUT    /api/investment-flow/v1/uninvested-cash/categories/:id   — update cash category
//   DELETE /api/investment-flow/v1/uninvested-cash/categories/:id   — delete cash category
//   GET    /api/investment-flow/v1/highlights                   — get node highlight color map
//   PATCH  /api/investment-flow/v1/highlights                   — set node highlight color map

const makeCategoryPayload = (overrides = {}) => ({
  node_type: 'category',
  name: 'Saham IDX',
  ...overrides,
})

const makeTickerPayload = (overrides = {}) => ({
  node_type: 'ticker',
  name: 'BBCA',
  nominal: 50000000,
  notes: 'Long term hold',
  ...overrides,
})

// ─── GET /api/investment-flow/v1 ─────────────────────────────────────────────

describe('Investment Flow API — GET /api/investment-flow/v1', () => {
  before(() => {
    cy.clearCookies()
    cy.clearLocalStorage()
    cy.setupApiAuthCookies()
  })

  beforeEach(() => {
    cy.setupApiAuthCookies()
  })

  it('returns 200 with valid session', () => {
    cy.listInvestmentFlowNodes().then((res) => {
      expect(res.status).to.eq(200)
    })
  })

  it('returns 401 when unauthenticated', () => {
    cy.clearCookies()
    cy.listInvestmentFlowNodesNoAuth().then((res) => {
      expect(res.status).to.be.oneOf([401, 307])
    })
  })

  it('returns success: true and data.nodes array', () => {
    cy.setupApiAuthCookies()
    cy.listInvestmentFlowNodes().then((res) => {
      expect(res.body).to.have.property('success', true)
      expect(res.body.data).to.have.property('nodes').that.is.an('array')
    })
  })

  it('returns expected node fields when list is non-empty', () => {
    cy.setupApiAuthCookies()
    cy.listInvestmentFlowNodes().then((res) => {
      if (res.body.data.nodes.length === 0) {
        cy.log('Tree is empty — skipping field shape check')
        return
      }
      const node = res.body.data.nodes[0]
      expect(node).to.have.property('id')
      expect(node).to.have.property('parent_id')
      expect(node).to.have.property('node_type').that.is.oneOf(['category', 'ticker'])
      expect(node).to.have.property('name').that.is.a('string')
      expect(node).to.have.property('sort_order').that.is.a('number')
      expect(node).to.have.property('created_at')
      expect(node).to.have.property('updated_at')
    })
  })

  it('returns uninvestedCash as a number alongside the node list', () => {
    cy.listInvestmentFlowNodes().then((res) => {
      expect(res.body.data).to.have.property('uninvestedCash').that.is.a('number')
    })
  })

  it('returns cashCategories as an array alongside the node list (issue #776)', () => {
    cy.listInvestmentFlowNodes().then((res) => {
      expect(res.body.data).to.have.property('cashCategories').that.is.an('array')
    })
  })

  it('returns highlights as an object alongside the node list (issue #781)', () => {
    cy.listInvestmentFlowNodes().then((res) => {
      expect(res.body.data).to.have.property('highlights').that.is.an('object')
    })
  })

  it('reflects a PATCHed highlight color in data.highlights (issue #781)', () => {
    cy.createInvestmentFlowNode(makeCategoryPayload({ name: 'Highlight Sync Category' })).then(
      (createRes) => {
        expect(createRes.status).to.eq(201)
        const nodeId = createRes.body.data.id

        cy.patchInvestmentFlowHighlights({ highlights: { [nodeId]: '#3B82F6' } }).then(
          (patchRes) => {
            expect(patchRes.status).to.eq(200)

            cy.listInvestmentFlowNodes().then((listRes) => {
              expect(listRes.body.data.highlights).to.have.property(nodeId, '#3B82F6')
            })
          }
        )
      }
    )
  })
})

// ─── POST /api/investment-flow/v1 ────────────────────────────────────────────

describe('Investment Flow API — POST /api/investment-flow/v1 (create)', () => {
  beforeEach(() => {
    cy.setupApiAuthCookies()
  })

  it('returns 201 when creating a valid category node at root level', () => {
    cy.createInvestmentFlowNode(makeCategoryPayload()).then((res) => {
      expect(res.status).to.eq(201)
      expect(res.body).to.have.property('success', true)
      const node = res.body.data
      expect(node).to.have.property('node_type', 'category')
      expect(node).to.have.property('nominal', null)
      expect(node).to.have.property('notes', null)
      expect(node).to.have.property('parent_id', null)
    })
  })

  it('returns 201 when creating a ticker node under a category (manual nominal)', () => {
    // Category (autosum) parent, ticker child holds the manual nominal
    cy.createInvestmentFlowNode(makeCategoryPayload({ name: 'Saham US' })).then((catRes) => {
      expect(catRes.status).to.eq(201)
      const parentId = catRes.body.data.id

      cy.createInvestmentFlowNode(makeTickerPayload({ parent_id: parentId })).then((res) => {
        expect(res.status).to.eq(201)
        const node = res.body.data
        expect(node).to.have.property('node_type', 'ticker')
        expect(node).to.have.property('nominal', 50000000)
        expect(node).to.have.property('parent_id', parentId)
      })
    })
  })

  it('returns 201 when creating a category node (autosum) under another category', () => {
    // node_type: 'category' means value is derived from children sum, not manual nominal
    cy.createInvestmentFlowNode(makeCategoryPayload({ name: 'Portfolio Root' })).then((rootRes) => {
      expect(rootRes.status).to.eq(201)
      const parentId = rootRes.body.data.id

      cy.createInvestmentFlowNode(
        makeCategoryPayload({ name: 'Saham IDX (autosum)', parent_id: parentId })
      ).then((res) => {
        expect(res.status).to.eq(201)
        const node = res.body.data
        expect(node).to.have.property('node_type', 'category')
        expect(node).to.have.property('nominal', null)
        expect(node).to.have.property('parent_id', parentId)
      })
    })
  })

  it('returns 201 when creating a nested ticker under a ticker (leaf with children)', () => {
    // Parent ticker's own nominal is superseded once it gains a child —
    // createNode.js clears parent.nominal/notes in this case.
    cy.createInvestmentFlowNode(makeTickerPayload({ name: 'Parent Ticker' })).then((parentRes) => {
      expect(parentRes.status).to.eq(201)
      const parentId = parentRes.body.data.id

      cy.createInvestmentFlowNode(
        makeTickerPayload({ name: 'Child Ticker', parent_id: parentId })
      ).then((res) => {
        expect(res.status).to.eq(201)
        expect(res.body.data).to.have.property('parent_id', parentId)

        cy.listInvestmentFlowNodes().then((listRes) => {
          const parentNode = listRes.body.data.nodes.find((n) => n.id === parentId)
          expect(parentNode).to.have.property('nominal', null)
        })
      })
    })
  })

  it('returns 401 when unauthenticated', () => {
    cy.clearCookies()
    cy.createInvestmentFlowNodeNoAuth(makeCategoryPayload()).then((res) => {
      expect(res.status).to.be.oneOf([401, 307])
    })
  })

  it('returns 400 when name is missing', () => {
    const payload = makeCategoryPayload()
    delete payload.name
    cy.createInvestmentFlowNode(payload).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when node_type is missing', () => {
    const payload = makeCategoryPayload()
    delete payload.node_type
    cy.createInvestmentFlowNode(payload).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when node_type is invalid', () => {
    cy.createInvestmentFlowNode({ ...makeCategoryPayload(), node_type: 'stock' }).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when ticker node is missing nominal', () => {
    const payload = makeTickerPayload()
    delete payload.nominal
    cy.createInvestmentFlowNode(payload).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when ticker nominal is negative or zero', () => {
    cy.createInvestmentFlowNode(makeTickerPayload({ nominal: -1 })).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when category node has nominal (cross-field violation)', () => {
    cy.createInvestmentFlowNode(makeCategoryPayload({ nominal: 100000 })).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when category node has notes (cross-field violation)', () => {
    cy.createInvestmentFlowNode(makeCategoryPayload({ notes: 'should not be here' })).then(
      (res) => {
        expect(res.status).to.eq(400)
        expect(res.body).to.have.property('error')
      }
    )
  })

  it('returns 400 when parent_id is a non-existent uuid', () => {
    cy.createInvestmentFlowNode(
      makeCategoryPayload({ parent_id: '00000000-0000-0000-0000-000000000000' })
    ).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('accepts optional notes field on ticker node', () => {
    cy.createInvestmentFlowNode(makeTickerPayload({ notes: 'dividend play' })).then((res) => {
      expect(res.status).to.eq(201)
      expect(res.body.data).to.have.property('notes', 'dividend play')
    })
  })

  it('returns 400 when notes exceed 500 characters', () => {
    cy.createInvestmentFlowNode(makeTickerPayload({ notes: 'a'.repeat(501) })).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  // NOTE: createNode.js enforces MAX_NODES_PER_USER = 500 (NODE_LIMIT_EXCEEDED -> 422).
  // cy.request() bypasses the browser network layer, so cy.intercept() cannot stub
  // this response, and seeding 500 real rows per run is too slow/expensive for CI.
  // This edge case is covered by Backend unit/integration tests instead — see
  // lib/services/investmentFlow/createNode.js and errorMessages.js.

  it('returns 422 with code INSUFFICIENT_CASH when node nominal exceeds cash category balance (issue #776)', () => {
    cy.createUninvestedCashCategory({ name: 'Small Pool', nominal: 100000 }).then((catRes) => {
      expect(catRes.status).to.eq(201)
      const categoryId = catRes.body.data.category.id

      cy.createInvestmentFlowNode(
        makeTickerPayload({
          name: 'Overdrawn Ticker',
          nominal: 999999999,
          uninvested_cash_category_id: categoryId,
        })
      ).then((res) => {
        expect(res.status).to.eq(422)
        expect(res.body).to.have.property('success', false)
        expect(res.body).to.have.property('code', 'INSUFFICIENT_CASH')
      })
    })
  })
})

