describe('Investment Flow API — PATCH /api/investment-flow/v1/uninvested-cash', () => {
  beforeEach(() => {
    cy.setupApiAuthCookies()
  })

  it('returns 200 and the updated amount when setting a valid value', () => {
    cy.patchUninvestedCash({ amount: 12500000 }).then((res) => {
      expect(res.status).to.eq(200)
      expect(res.body).to.have.property('success', true)
      expect(res.body.data).to.have.property('uninvestedCash', 12500000)
    })
  })

  it('persists the updated value on subsequent GET', () => {
    cy.patchUninvestedCash({ amount: 3000000 }).then(() => {
      cy.getUninvestedCash().then((res) => {
        expect(res.body.data).to.have.property('uninvestedCash', 3000000)
      })
    })
  })

  it('accepts 0 as a valid amount (reset to default)', () => {
    cy.patchUninvestedCash({ amount: 0 }).then((res) => {
      expect(res.status).to.eq(200)
      expect(res.body.data).to.have.property('uninvestedCash', 0)
    })
  })

  it('returns 401 when unauthenticated', () => {
    cy.clearCookies()
    cy.patchUninvestedCashNoAuth({ amount: 1000000 }).then((res) => {
      expect(res.status).to.be.oneOf([401, 307])
    })
  })

  it('returns 400 when amount is missing', () => {
    cy.patchUninvestedCash({}).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when amount is a string instead of a number', () => {
    cy.patchUninvestedCash({ amount: 'not-a-number' }).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })

  it('returns 400 when amount is negative', () => {
    cy.patchUninvestedCash({ amount: -500 }).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('error')
    })
  })
})

