describe('Investment Flow API — PUT /api/investment-flow/v1/uninvested-cash/categories/:id', () => {
  let categoryId

  before(() => {
    cy.clearCookies()
    cy.clearLocalStorage()
    cy.setupApiAuthCookies()
    cy.createUninvestedCashCategory({ name: 'Update Test Pool', nominal: 2000000 }).then((res) => {
      expect(res.status).to.eq(201)
      categoryId = res.body.data.category.id
    })
  })

  beforeEach(() => {
    cy.setupApiAuthCookies()
  })

  it('returns 200 when updating name and nominal', () => {
    cy.updateUninvestedCashCategory(categoryId, {
      name: 'Renamed Pool',
      nominal: 3000000,
    }).then((res) => {
      expect(res.status).to.eq(200)
      expect(res.body).to.have.property('success', true)
      expect(res.body.data.category).to.have.property('name', 'Renamed Pool')
      expect(res.body.data.category).to.have.property('nominal', 3000000)
    })
  })

  it('returns 200 when updating only name', () => {
    cy.updateUninvestedCashCategory(categoryId, { name: 'Name Only Update' }).then((res) => {
      expect(res.status).to.eq(200)
      expect(res.body.data.category).to.have.property('name', 'Name Only Update')
    })
  })

  it('returns 401 when unauthenticated', () => {
    cy.clearCookies()
    cy.updateUninvestedCashCategoryNoAuth(categoryId, { name: 'Hacked Pool' }).then((res) => {
      expect(res.status).to.be.oneOf([401, 307])
    })
  })

  it('returns 400 when id is not a valid uuid', () => {
    cy.updateUninvestedCashCategory('not-a-uuid', { name: 'Bad ID' }).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('success', false)
    })
  })

  it('returns 404 when id is a valid uuid but category does not exist', () => {
    cy.updateUninvestedCashCategory('00000000-0000-0000-0000-000000000000', {
      name: 'Ghost Pool',
    }).then((res) => {
      expect(res.status).to.eq(404)
      expect(res.body).to.have.property('success', false)
    })
  })

  it('returns 400 when nominal is negative', () => {
    cy.updateUninvestedCashCategory(categoryId, { nominal: -100 }).then((res) => {
      expect(res.status).to.eq(400)
      expect(res.body).to.have.property('success', false)
    })
  })
})

